var t=`0660-moi-moi`;var a=`world-0660`;var n=`NG`;var o=`western-africa`;var s=8;var r=569;var l={en:`Moi Moi`,ua:`Мої-мої`};var d={en:`Moi Moi is a Nigeria classic prepared with black-eyed peas, red bell pepper, yellow onion, crayfish. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Мої-мої, страва кухні країни Нігерія зі складниками: квасоля чорноочка, червоний солодкий перець, жовта цибуля, річковий рак. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Soak the dried beans or peas in plentiful cold water for 480 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 480 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:480,i:[[`black-eyed-peas`,430,`g`],[`water`,900,`ml`]]},{en:`Blend peeled soaked black-eyed peas with peppers, onion and water to a light smooth batter, then beat in palm oil.`,ua:`Збийте вимочений очищений чорноокий горох із перцем, цибулею та водою до гладкого легкого тіста, додайте пальмову олію.`,t:[`mixing`],m:15,i:[[`red-bell-pepper`,220,`g`],[`yellow-onion`,140,`g`],[`red-palm-oil`,65,`ml`],[`water`,320,`ml`],[`crayfish`,80,`g`],[`table-salt`,null,`to_taste`]]},{en:`Boil the eggs for about 10 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 10 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:10,i:[[`chicken-egg`,2,`pcs`]]},{en:`Divide batter between heatproof ramekins or suitable food-safe leaves, leaving room for expansion; cover tightly, adding slices of the cooked eggs.`,ua:`Розподіліть тісто по жаростійких формочках або безпечних харчових листках, залишаючи місце для розширення; додайте скибочки варених яєць і щільно накрийте.`,t:[`basket-steaming`],m:12,i:[]},{en:`Steam covered portions for about 48 minutes until the center is set and fully cooked; serve warm.`,ua:`Готуйте накриті порції на парі близько 48 хвилин до повного схоплення середини; подавайте теплими.`,t:[`steaming`],m:48,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[]}];var m={slug:t,id:a,country:`NG`,region:o,servings:8,minutes:569,title:l,text:d,steps:g};export{n as country,m as default,a as id,r as minutes,o as region,s as servings,t as slug,g as steps,d as text,l as title};